<script setup lang="ts">import {ref} from 'vue';import {useRouter} from 'vue-router';import {ScanLine,CheckCircle2,ChevronDown} from 'lucide-vue-next';import PageHeader from '../components/PageHeader.vue';import {vehicles} from '../data/mock';import {useVintro} from '../composables/useVintro';const router=useRouter();const {notify}=useVintro();const vin=ref('');const state=ref<'input'|'loading'|'found'>('input');const manual=ref(false);const manualForm=ref({make:'Audi',model:'A4 Avant',year:2019,engine:'2.0 TDI',registration:'ZH 921 440',mileage:96500});const find=()=>{if(vin.value.length!==17)return;state.value='loading';setTimeout(()=>state.value='found',750)};const add=()=>setTimeout(()=>router.push('/vehicle/bmw-320d'),400);const addManual=()=>{vehicles.push({id:`${manualForm.value.make}-${manualForm.value.model}`.toLowerCase().replace(/\s+/g,'-'),vin:'Not provided',make:manualForm.value.make,model:manualForm.value.model,trim:manualForm.value.engine,year:Number(manualForm.value.year),mileage:Number(manualForm.value.mileage),fuelType:'Diesel',power:'—',transmission:'Manual',registration:manualForm.value.registration,image:vehicles[0].image,health:'Up to date',ownershipStatus:'Current',ownershipSince:'August 2026',firstRegistration:'Not provided'});notify('Vehicle added manually');router.push('/')}

</script>
<template><PageHeader title="Add vehicle" back="/"/><div class="container-app max-w-2xl py-8"><div v-if="state!=='found'"><span class="grid h-12 w-12 place-items-center rounded-2xl bg-ink text-white"><ScanLine/></span><h1 class="page-title mt-6">Add your vehicle</h1><p class="mt-3 text-muted">Enter the VIN and we'll identify the vehicle.</p><form class="mt-8" @submit.prevent="find"><label><span class="label">Vehicle identification number</span><input v-model.trim="vin" maxlength="17" class="field nums uppercase tracking-[.08em]" placeholder="17-character VIN" required/></label><p v-if="vin&&vin.length!==17" class="mt-2 text-xs text-amber">A VIN contains 17 characters.</p><button class="btn-primary mt-5 w-full" :disabled="vin.length!==17||state==='loading'"><span v-if="state==='loading'" class="h-4 w-4 animate-spin rounded-full border-2 border-white/40 border-t-white"/>{{state==='loading'?'Identifying vehicle…':'Find vehicle'}}</button><button v-if="!vin" type="button" @click="vin='WBA8K91070K123456'" class="mt-3 w-full py-2 text-sm font-medium text-accent">Use demo VIN</button></form><button @click="manual=!manual" class="mt-8 flex w-full items-center justify-between border-t pt-6 text-sm font-medium">Enter vehicle manually<ChevronDown :size="17" :class="{'rotate-180':manual}"/></button><form v-if="manual" @submit.prevent="addManual" class="mt-5 grid gap-4 sm:grid-cols-2"><label><span class="label">Make</span><input v-model="manualForm.make" class="field" required/></label><label><span class="label">Model</span><input v-model="manualForm.model" class="field" required/></label><label><span class="label">Year</span><input v-model="manualForm.year" class="field" type="number" required/></label><label><span class="label">Engine / version</span><input v-model="manualForm.engine" class="field"/></label><label><span class="label">Registration</span><input v-model="manualForm.registration" class="field"/></label><label><span class="label">Current mileage</span><input v-model="manualForm.mileage" class="field nums" type="number" required/></label><button class="btn-primary sm:col-span-2">Add vehicle manually</button></form></div><div v-else><div class="flex items-center gap-2 text-sm font-semibold text-success"><CheckCircle2 :size="19"/>Vehicle found</div><div class="card mt-5 overflow-hidden"><img :src="vehicles[0].image" class="h-56 w-full object-cover" alt="BMW 320d Touring"/><div class="p-6"><p class="eyebrow">M Sport · G21</p><h1 class="mt-2 text-2xl font-semibold">BMW 320d Touring</h1><div class="mt-5 grid grid-cols-2 gap-4 text-sm sm:grid-cols-4"><span><small class="block text-muted">Year</small>2020</span><span><small class="block text-muted">Engine</small>2.0 Diesel</span><span><small class="block text-muted">Power</small>190 hp</span><span><small class="block text-muted">Gearbox</small>Automatic</span></div></div></div><button @click="add" class="btn-primary mt-5 w-full">Add to Garage</button><button @click="state='input'" class="mt-3 w-full py-2 text-sm text-muted">Use a different VIN</button></div></div></template>
